insert into public.exam_questions (subject, question, options, answer) values ('예배모범', '성례가 ''거룩한 예식''으로 불리는 주된 이유는?', '["교인들이 많이 참여하기 때문", "오랜 전통을 가지고 있기 때문", "특별한 장소에서만 시행되기 때문", "그리스도께서 직접 제정하시고 특별한 은혜가 담겨 있기 때문"]'::jsonb, 3);
