insert into public.exam_questions (subject, question, options, answer) values ('예배모범', '성례는 단지 상징적인 의미만을 가집니까?', '["그렇다", "아니다, 영적인 유익과 은혜가 있다", "믿지 않는 자에게는 의미가 없다.", "교인들의 참여 여부에 따라 의미가 달라진다."]'::jsonb, 1);
