insert into public.exam_questions (subject, question, options, answer) values ('예배모범', '유아세례의 성경적 근거로 제시된 것은?', '["구약의 할례, 예수께서 어린이를 축복한 것, 사도 시대 어린이들도 세례를 받은 것", "구약의 제사 의식", "예수님의 성인 세례만", "성경에는 유아세례 근거가 없다."]'::jsonb, 0);
