insert into public.exam_questions (subject, question, options, answer) values ('예배모범', '교회의 권세 세 가지가 있다. 그 중에 들지 않는 것은?', '["교황권", "교리권", "치리권", "봉사(사역)권"]'::jsonb, 0);
